	@Test
	void serviceAndPathChildrenReceiveTheirApplicableJoinInput() {
		Value endpoint = VF.createIRI("urn:service");
		Service service = new Service(Var.of("endpoint"),
				new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("object")), "", Map.of(), null,
				false);
		Join serviceJoin = new Join(values("endpoint", endpoint), service);
		QueryAlgebraBindingAnalysis serviceAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(serviceJoin,
				EmptyBindingSet.getInstance());
		QueryAlgebraBindingAnalysis.ReadOnlyContext serviceInput = serviceAnalysis.contextAt(service.getServiceExpr());

		assertThat(serviceInput.guaranteedNames()).contains("endpoint");
		assertThat(serviceInput.fixedValues().get("endpoint")).isEqualTo(endpoint);

		Value subject = VF.createIRI("urn:path-start");
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("start"),
				new StatementPattern(Var.of("start"), Var.of("pathPredicate"), Var.of("pathObject")), Var.of("end"), 1);
		Join pathJoin = new Join(values("start", subject), path);
		QueryAlgebraBindingAnalysis pathAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(pathJoin,
				EmptyBindingSet.getInstance());
		QueryAlgebraBindingAnalysis.ReadOnlyContext pathInput = pathAnalysis.contextAt(path.getPathExpression());

		assertThat(pathInput.guaranteedNames()).contains("start");
		assertThat(pathInput.fixedValues().get("start")).isEqualTo(subject);
		assertThat(pathAnalysis.outputFacts(path, pathAnalysis.contextAt(path)).possibleOutputsKnown()).isTrue();
	}

